const QELVIORA_ENQUIRY_ROUTES={"Service":[{"label":"Web & App Development","path":"index.html#services"},{"label":"AI Automation","path":"index.html#services"},{"label":"Business Analysis","path":"index.html#services"},{"label":"Data Analysis","path":"index.html#services"},{"label":"SEO","path":"index.html#services"},{"label":"Digital Marketing","path":"index.html#services"},{"label":"Lead Generation","path":"index.html#services"},{"label":"Google Business Profile Optimization","path":"index.html#services"}],"Internship":[{"label":"Data Analytics Internship","path":"internship-application.html?domain=Data%20Analytics"},{"label":"AI/ML Internship","path":"internship-application.html?domain=AI%2FML"},{"label":"Web Development Internship","path":"internship-application.html?domain=Web%20Development"},{"label":"Business Analytics Internship","path":"internship-application.html?domain=Business%20Analytics"},{"label":"Digital Marketing Internship","path":"internship-application.html?domain=Digital%20Marketing"},{"label":"UI/UX Internship","path":"internship-application.html?domain=UI%2FUX"},{"label":"Cybersecurity Internship","path":"internship-application.html?domain=Cybersecurity"}],"Training":[{"label":"Full Stack Development","path":"program-full-stack-development.html"},{"label":"Frontend Development","path":"program-frontend-development.html"},{"label":"Backend Development","path":"program-backend-development.html"},{"label":"Data Analyst","path":"program-data-analyst.html"},{"label":"Data Science","path":"program-data-science.html"},{"label":"Generative AI","path":"program-generative-ai.html"},{"label":"Human Resource","path":"program-human-resource.html"},{"label":"Business Analyst","path":"program-business-analyst.html"},{"label":"Artificial Intelligence","path":"program-artificial-intelligence.html"},{"label":"Machine Learning","path":"program-machine-learning.html"},{"label":"Communication Skills","path":"program-communication-skills.html"}],"Programs":[{"label":"Training Catalogue","path":"programs.html"},{"label":"Projects","path":"projects.html"},{"label":"Career Center","path":"career-center.html"},{"label":"Skill Guides","path":"skills.html"},{"label":"Find Your Path","path":"career-path.html"}]};
(()=>{
if(!/\/(?:index\.html)?$/.test(location.pathname))return;
const dialog=document.createElement("dialog");dialog.className="enquiry-popup";dialog.setAttribute("aria-labelledby","popup-title");
dialog.innerHTML='<button class="popup-close" type="button" aria-label="Close enquiry">×</button><p class="eyebrow">FIND YOUR NEXT STEP</p><h2 id="popup-title">How can we help?</h2><p>Share your interest. After submission, continue to the relevant page.</p><form id="popup-enquiry-form" action="https://formsubmit.co/qelvioratechnologies@gmail.com" method="POST"><input type="hidden" name="_subject" value="Qelviora Guided Website Enquiry"><input type="hidden" name="_template" value="table"><input id="popup-next" type="hidden" name="_next"><input class="honeypot" name="_honey" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="form-grid"><label>Full Name *<input name="name" autocomplete="name" required maxlength="120"></label><label>Email *<input name="email" type="email" autocomplete="email" required></label><label>Phone *<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{7,20}"></label><label>Enquiry Type *<select name="enquiry_type" id="popup-category" required><option value="">Choose your interest</option><option>Service</option><option>Internship</option><option>Training</option><option>Programs</option></select></label></div><label>Your Interest *<select name="interest" id="popup-interest" required disabled><option value="">Choose a category first</option></select></label><label>Message (optional)<textarea name="message" rows="3" maxlength="2000"></textarea></label><label class="consent"><input name="consent" type="checkbox" required value="Agreed"><span>I agree to share these details with Qelviora Technologies and its form delivery service so the team can respond.</span></label><div class="popup-actions"><button class="button" type="submit">Send Enquiry & Continue</button><button class="button outline" id="popup-browse" type="button" disabled>Browse Without Enquiry</button></div><p id="popup-route-note" class="fine">Select a category and interest to see your next page.</p><p id="popup-status" role="status"></p><p class="fine">The form service completes your submission and redirects you. This is an enquiry, not confirmed enrolment or payment.</p></form>';
document.body.append(dialog);
const category=dialog.querySelector("#popup-category"),interest=dialog.querySelector("#popup-interest"),next=dialog.querySelector("#popup-next"),browse=dialog.querySelector("#popup-browse"),note=dialog.querySelector("#popup-route-note"),status=dialog.querySelector("#popup-status");
function destination(){return QELVIORA_ENQUIRY_ROUTES[category.value]?.find(r=>r.label===interest.value)}
function updateRoute(){const route=destination();browse.disabled=!route;next.value=route?new URL(route.path,location.href).href:"";note.textContent=route?"After submission, continue to: "+route.label+".":"Choose your specific interest."}
category.addEventListener("change",()=>{interest.replaceChildren(new Option("Choose your interest",""));const rows=QELVIORA_ENQUIRY_ROUTES[category.value]||[];interest.disabled=!rows.length;rows.forEach(r=>interest.add(new Option(r.label,r.label)));updateRoute()});interest.addEventListener("change",updateRoute);
dialog.querySelector(".popup-close").onclick=()=>dialog.close();dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
browse.onclick=()=>{const route=destination();if(route)location.href=route.path};
dialog.querySelector("form").addEventListener("submit",e=>{if(location.protocol==="file:"){e.preventDefault();status.textContent="Extract the ZIP and open Launch Website.cmd before submitting.";return}updateRoute();if(!destination()){e.preventDefault();return}status.textContent="Continuing to the form service. Complete submission to reach your selected page.";});
let shown=false;try{shown=sessionStorage.getItem("qelviora-enquiry-shown")==="yes"}catch{}
function checkHomepageEnd(){if(shown||window.scrollY<=0)return;const page=document.documentElement;if(window.scrollY+window.innerHeight<page.scrollHeight-24)return;if(document.querySelector("dialog[open]")||document.querySelector("#assistant-panel:not([hidden])"))return;dialog.showModal();shown=true;try{sessionStorage.setItem("qelviora-enquiry-shown","yes")}catch{}window.removeEventListener("scroll",checkHomepageEnd)}
if(!shown)window.addEventListener("scroll",checkHomepageEnd,{passive:true});
})();
